		fmt.Println("全局中间件 前")
		c.Next()
		fmt.Println("全局中间件 后")
	})
	g := r.Group("/api", func(c *gin.Context) {
		fmt.Println("组中间件 前")
		c.Next()
		fmt.Println("组中间件 后")
	})
	g.GET("/x", func(c *gin.Context) {
		fmt.Println("处理函数")
		c.String(200, "ok")
	})

	w := httptest.NewRecorder()
	req := httptest.NewRequest("GET", "/api/x", nil)
	r.ServeHTTP(w, req)
	fmt.Println("状态码:", w.Code)
}

