import (
	"fmt"
	"net/http/httptest"
	"time"

	"github.com/gin-gonic/gin"
)

// Cost 统计整条 handler 链的耗时
func Cost() gin.HandlerFunc {
	return func(c *gin.Context) {
		start := time.Now()
		defer func() {
			cost := time.Since(start)
			c.Set("cost", cost) // 存进 Context，其实链已经走完没人会读
			fmt.Printf("%s 耗时 %s\n", c.FullPath(), cost)
		}()
		c.Next() // 先让后面的处理函数跑完
	}
}

func main() {
	gin.SetMode(gin.ReleaseMode)
	r := gin.New()
	r.Use(Cost())
	r.GET("/slow", func(c *gin.Context) {
		time.Sleep(10 * time.Millisecond)
		c.String(200, "ok")
	})

	w := httptest.NewRecorder()
	req := httptest.NewRequest("GET", "/slow", nil)
	r.ServeHTTP(w, req)
	fmt.Println("状态码:", w.Code)
}

package main

import (
	"fmt"
	"net/http/httptest"

	"github.com/gin-gonic/gin"
)

// Recovery 兜住后面所有 handler 抛出的 panic
func Recovery() gin.HandlerFunc {
	return func(c *gin.Context) {
		defer func() {
			if err := recover(); err != nil {
				fmt.Println("捕获到 panic:", err)
				c.AbortWithStatusJSON(500, gin.H{"error": "internal server error"})
			}
		}()
		c.Next()
	}
}

func main() {
	gin.SetMode(gin.ReleaseMode)
	r := gin.New()
	r.Use(Recovery()) // 要放在最前面，才能兜住后面所有 handler
	r.GET("/boom", func(c *gin.Context) {
		panic("boom")
	})

	w := httptest.NewRecorder()
	req := httptest.NewRequest("GET", "/boom", nil)
	r.ServeHTTP(w, req)
	fmt.Printf("code=%d body=%s\n", w.Code, w.Body.String())
}

package main

import (
	"fmt"
	"net/http/httptest"

	"github.com/gin-gonic/gin"
)

func main() {
	gin.SetMode(gin.ReleaseMode)
	r := gin.New()
	var saved *gin.Context
	r.GET("/user/:id", func(c *gin.Context) {
		if saved == nil {
			saved = c // 错误示范：把 *gin.Context 存下来
		}
		c.String(200, "ok")
	})

	w := httptest.NewRecorder()
	r.ServeHTTP(w, httptest.NewRequest("GET", "/user/1", nil))
	fmt.Println("第一个请求结束")

	w = httptest.NewRecorder()
	r.ServeHTTP(w, httptest.NewRequest("GET", "/user/2", nil))
	fmt.Println("第二个请求结束")

	// saved 是被复用的同一个 Context，内容已经被第二个请求覆盖
	fmt.Printf("saved.Param(id)=%s saved.Request=%s\n", saved.Param("id"), saved.Request.URL.Path)
}
